#!/usr/bin/env bash
# Code Generated by Sidekick is for learning and experimentation purposes only.
set -euo pipefail

echo "==> Stage 7: grafana dashboards + datasources"

# 1. Path Configuration
# If running inside GitHub Actions, REPO_ROOT resolves to the repository root workspace.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DASH_DIR="${REPO_ROOT}/metrics/grafana/provisioning/dashboards"

# 2. Environment Variable Fallbacks (Ensures it works standalone or when called via CI)
export OBS_NAMESPACE="${OBS_NAMESPACE:-ibts-observability}"
NS="$OBS_NAMESPACE"
echo "==> Targeted Namespace: ${NS}"
GRAFANA_FOLDER="${GRAFANA_FOLDER:-IBTS}"

# 3. Process Dashboard JSON Files
shopt -s nullglob
dash_files=("${DASH_DIR}"/*.json)
shopt -u nullglob

if (( ${#dash_files[@]} == 0 )); then
  echo "  [WARN] no dashboard JSON files found in ${DASH_DIR}"
else
  for f in "${dash_files[@]}"; do
    base=$(basename "$f" .json)

    # Fail early on invalid JSON structure
    if command -v jq >/dev/null 2>&1; then
      jq empty "$f" || { echo "  [FAIL] invalid JSON: $f"; exit 1; }
    fi

    # DNS-1123 compliance: lowercase names, replace underscores AND dots with dashes
    cm_name="grafana-dash-$(echo "$base" | tr '_A-Z.' '-a-z-')"

    # Create sidecar-friendly ConfigMaps using server-side apply
    kubectl create configmap "$cm_name" -n "$NS" \
        --from-file="${base}.json=${f}" --dry-run=client -o yaml \
      | kubectl label    --local -f - grafana_dashboard=1 -o yaml \
      | kubectl annotate --local -f - "grafana_folder=${GRAFANA_FOLDER}" -o yaml \
      | kubectl apply -n "$NS" --server-side --force-conflicts -f -

    echo "  [OK] dashboard loaded: ${base} -> ConfigMap: ${cm_name}"
  done
fi

# 4. Apply Jaeger Datasource
echo "  [INFO] Registering Jaeger datasource target in namespace: ${NS}"
kubectl apply -n "$NS" -f - << EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: grafana-ds-jaeger
  labels:
    grafana_datasource: "1"
data:
  jaeger-datasource.yaml: |-
    apiVersion: 1
    datasources:
      - name: Jaeger
        uid: jaeger
        type: jaeger
        access: proxy
        url: http://jaeger-query.${NS}.svc.cluster.local:80
        isDefault: false
EOF

echo "  [OK] dashboards + Jaeger datasource applied"

# 5. Output Verification
echo "==> Summary of dashboards in ${NS}:"
kubectl get cm -n "$NS" -l grafana_dashboard=1
